def ids(*names):
    return [IDS[n] for n in names]

def ch(number, slug, title, purpose, questions, primary, secondary, repo, conf, research):
    return {
        "number": number,
        "file": "docs/textbook/%s-%s.md" % (number, slug),
        "title": title,
        "purpose": purpose,
        "questions_answered": questions,
        "artifacts_primary": ids(*primary),
        "artifacts_secondary": ids(*secondary),
        "repository_sources": repo,
        "confidentiality": conf,
        "research_needed": research,
    }

